-- Stage 3 / Task 2: an APPROVED_FOR_REVIEW decision must carry a SIZED position size (NULL counts as not sized: every term is coalesced to false). NOT VALID:
-- enforced for every new row; rows written before this migration (none in staging; only test databases) are preserved untouched, never rewritten.
ALTER TABLE "risk_decisions" ADD CONSTRAINT "risk_decisions_sized_review_check" CHECK ("risk_decisions"."status" <> 'APPROVED_FOR_REVIEW' or (coalesce("risk_decisions"."planned_quantity" > 0, false) and coalesce("risk_decisions"."planned_notional" > 0, false) and coalesce("risk_decisions"."planned_max_loss_amount" > 0, false) and coalesce("risk_decisions"."planned_max_loss_percent" > 0, false) and coalesce("risk_decisions"."output_snapshot" -> 'sizing' ->> 'status' = 'SIZED', false))) NOT VALID;
